# The library of the Mac tasks. It has the names of the shell Mac helpers, and
# each print function writes the same bytes as the shell function of the same
# name. print_header and print_subheader are the exception: they write the
# lines, the emojis and the colors of the repo library. A task imports it after it adds the _scripts folder to sys.path:
#
#   sys.dont_write_bytecode = True
#   sys.path.insert(0, os.path.expanduser("~/.config/mise/tasks/_scripts"))
#   import helpers
#
# It is not the helpers of repo/tools/: the Mac has its own library.

import os
import subprocess
import sys

# Color codes
GREEN = "\033[0;32m"
YELLOW = "\033[0;33m"
RED = "\033[0;31m"
BOLD = "\033[1m"
NORMAL = "\033[0m"

# Emojis
SUCCESS_EMOJI = "✅"
ERROR_EMOJI = "🚫"
# The emojis of a header and a subheader: the ones of the repo library.
EMOJI_HEADER = "🚀"
EMOJI_SUBHEADER = "📌"

_SIMPLE_ESCAPES = {
  ord("\\"): b"\\",
  ord("a"): b"\a",
  ord("b"): b"\b",
  ord("e"): b"\033",
  ord("E"): b"\033",
  ord("f"): b"\f",
  ord("n"): b"\n",
  ord("r"): b"\r",
  ord("t"): b"\t",
  ord("v"): b"\v",
}
_OCTAL = b"01234567"
_HEX = b"0123456789abcdefABCDEF"


def _expand_escapes(data):
  """Expand the backslash escapes of data (bytes) as echo -e of bash does.

  Returns (bytes, stop). stop is True when data has a \\c escape: the shell
  then stops all output, also the newline after the line. Different from
  printf %b, an octal escape must start with \\0.
  """
  out = bytearray()
  i = 0
  n = len(data)
  while i < n:
    c = data[i]
    if c != ord("\\") or i + 1 >= n:
      out.append(c)
      i += 1
      continue
    e = data[i + 1]
    if e in _SIMPLE_ESCAPES:
      out += _SIMPLE_ESCAPES[e]
      i += 2
    elif e == ord("c"):
      return bytes(out), True
    elif e == ord("0"):
      j = i + 2
      while j < n and j < i + 5 and data[j] in _OCTAL:
        j += 1
      out.append(int(data[i + 2 : j] or b"0", 8) & 0xFF)
      i = j
    elif e == ord("x") and i + 2 < n and data[i + 2] in _HEX:
      j = i + 2
      while j < n and j < i + 4 and data[j] in _HEX:
        j += 1
      out.append(int(data[i + 2 : j], 16))
      i = j
    elif e in (ord("u"), ord("U")) and i + 2 < n and data[i + 2] in _HEX:
      digits = 4 if e == ord("u") else 8
      j = i + 2
      while j < n and j < i + 2 + digits and data[j] in _HEX:
        j += 1
      out += chr(int(data[i + 2 : j], 16)).encode("utf-8", "surrogateescape")
      i = j
    else:
      out += data[i : i + 2]
      i += 2
  return bytes(out), False


def _write(data):
  """Write the bytes data to stdout and flush it, so the output of a command
  that the task runs next comes after it."""
  sys.stdout.flush()
  sys.stdout.buffer.write(data)
  sys.stdout.buffer.flush()


def _echo(text, newline=True):
  """Print text as echo -e (newline True) or echo -en (newline False)."""
  data, stop = _expand_escapes(text.encode("utf-8", "surrogateescape"))
  if newline and not stop:
    data += b"\n"
  _write(data)


def _join(args):
  """Join the arguments with spaces, as "$*" of the shell does."""
  return " ".join(str(a) for a in args)


def _titled(emoji, codes, msg):
  """The emoji, then the message in the codes; only the emoji when the message
  is empty. The form of the titles of the repo library."""
  return f"{emoji} {codes}{msg}{NORMAL}" if msg else emoji


# A major section: the header line, then the emoji and the title in green and
# bold. The arguments are joined with spaces.
def print_header(*msg):
  line_sep("──── ⋆⋅☆⋅⋆ ────")
  _echo(_titled(EMOJI_HEADER, f"{GREEN}{BOLD}", _join(msg)))


# A step in a section: the subheader line, then the emoji and the title in
# green. Not bold, so a step shows as a part of its section.
def print_subheader(*msg):
  line_sep("⋅")
  _echo(_titled(EMOJI_SUBHEADER, GREEN, _join(msg)))


# Print colored section header without new line
def print_wait(msg):
  _echo(f"{YELLOW}{BOLD}{msg}{NORMAL}", newline=False)


# Print empty line
def print_newline():
  _write(b"\n")


def print_error(msg):
  _echo(f"{ERROR_EMOJI} {RED}{BOLD}{msg}{NORMAL}")


def print_success(msg):
  _echo(f"{SUCCESS_EMOJI} {GREEN}{BOLD}{msg}{NORMAL}")


def print_warn(msg):
  _echo(f"{YELLOW}{BOLD}{msg}{NORMAL}")


# Print line separator: the pattern repeated, then cut to the width of the
# terminal on stdin, else 80, so a pattern of more than one character never
# wraps. The patterns of print_header and print_subheader are the ones of the
# repo library. Keep patterns to single-width characters.
def line_sep(pattern):
  try:
    width = os.get_terminal_size(0).columns
  except (OSError, ValueError):
    width = 80
  pattern = pattern or "="
  reps = (width + len(pattern) - 1) // len(pattern)
  _write(f"{(pattern * reps)[:width]}\n".encode("utf-8", "surrogateescape"))


# True when the mise task <task> exists: the tool that ships it is selected
def task_exists(task):
  try:
    return (
      subprocess.run(
        ["mise", "tasks", "info", task],
        check=False,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
      ).returncode
      == 0
    )
  except OSError:
    return False


# Run the mise task <task> [args...] when it exists, else skip it with a log
# line: the tasks of an opt-in tool exist only when that tool is selected.
# Returns the exit code of mise run, or 0 for a skip.
def run_task_if_exists(task, *args):
  if task_exists(task):
    return subprocess.run(["mise", "run", task, *args], check=False).returncode
  print_warn(f"Skipping {task}: no such task (its tool is not selected)")
  return 0
